function() {
    var re = /[\[\.]/;
    return function(expr) {
        if (Ext.isEmpty(expr)) {
            return Ext.emptyFn;
        }
        if (Ext.isFunction(expr)) {
            return expr;
        }
        if (this.useSimpleAccessors !== true) {
            var i = String(expr).search(re);
            if (i >= 0) {
                return Ext.functionFactory('obj', 'return obj' + (i > 0 ? '.' : '') + expr);
            }
        }
        return function(obj) {
            return obj[expr];
        };
    };
}()

